INSERT INTO business_profile (legal_name, brand_name, cin, registered_office, farm_name, farm_address, survey_numbers, farm_land_extent, land_status, bird_capacity, bird_type, housing_system, water_source, power_source, year_of_report, project_cost_paise, term_loan_paise, promoter_contribution_paise, cash_credit_limit_paise, project_status, notes)
SELECT 'Dhruva Natural Bio Products Pvt Ltd','6EGGZ Poultry Farms','U01122TS2023PTC178987','Plot No. 19, 4-59/6/19, Thumkunta, Shamirpet, Medchal, Telangana 500078','6EGGZ Environment-Controlled Commercial Layer Poultry Farm','Sy. No. 83D, Cheelapur Village, Bejjanki Mandal, Siddipet District, Telangana 505528','Sy. No. 83D','6 Acres 18 Guntas','Long-term leasehold land (as stated in DPR)',100000,'Commercial layer birds (BV300 noted in DPR technical assumptions)','Environment-controlled multi-tier layer housing with automated feeding, nipple drinking, egg collection, manure handling and tunnel ventilation','Borewell water supply','Grid electricity with backup power arrangement','DPR submitted August 2026',1200000000,800000000,400000000,200000000,'Proposed project — DPR assumptions, not a live operations statement','DPR financial model: total project cost ₹12.00 crore; proposed bank term loan ₹8.00 crore; promoter contribution ₹4.00 crore; cash-credit limit ₹2.00 crore. Model assumptions include average lay-day rate 88%, 315 saleable eggs/bird/year, mortality 5%, egg realization ₹6.00 in Years 1–2 rising to ₹6.48 in Year 8. These are model assumptions, not verified current retail prices, current bird count, sanctioned funding or current production.'
WHERE NOT EXISTS (SELECT 1 FROM business_profile WHERE legal_name='Dhruva Natural Bio Products Pvt Ltd' AND farm_name='6EGGZ Environment-Controlled Commercial Layer Poultry Farm');

INSERT INTO rnd_projects (project_code,name,alternate_name,product_concept,research_question,candidate_nutrients,scientific_rationale,evidence_references,project_owner,status,protocol_summary,baseline_summary,feed_trial_details,laboratory_plan,cost_notes,milestones,risks_and_limitations,commercial_release_approved)
SELECT '6EGGZ-RND-CHILD-001','6eggz Growing Years','6eggz Smart Nutrition Egg','Proposed family-nutrition egg concept; Research Concept — Not Approved for Commercial Sale.','Can qualified feed formulation and controlled production trials produce a repeatable, safe, measurable change in selected egg nutrients while maintaining flock health, egg quality, shelf stability and commercial feasibility?','["DHA / total omega-3","Choline and phosphatidylcholine where feasible","Iodine","Vitamin B12","Folate","Iron","Zinc","Protein / amino-acid profile","Optional separate targets: Vitamin D, selenium, lutein/zeaxanthin"]'::jsonb,'The uploaded Children’s Nutrition Egg R&D concept says these nutrients have roles in normal growth, neural development or function, but increasing nutrients above adequacy does not prove improved cognition. First establish baseline feed and ordinary egg composition; a composition study alone cannot support memory, IQ, concentration or academic-performance claims.','[{"source":"6eggz_Brain_Growth_Childrens_Nutrition_Egg_RnD_Report(1).docx","sections":["Executive recommendation","Candidate nutrient targets","Layer-feed development brief","Controlled egg-enrichment trial design","Accreditation, ethics and regulatory route","Suggested launch gates G0–G6"]},{"title":"FSSAI Advertising & Claims Regulations and amendments","url":"https://www.fssai.gov.in/food-law/regulations/amendments/advertising-claims"},{"title":"FSSAI food testing laboratories","url":"https://www.fssai.gov.in/food-testing/food-laboratories"},{"title":"NABL laboratory search","url":"https://nablwp.qci.org.in/laboratorysearch"},{"title":"FSSAI product standards","url":"https://www.fssai.gov.in/standards/product-standards"}]'::jsonb,'Dhruva Natural Bio Products Pvt Ltd — R&D owner to be assigned','Proposed','Obtain a signed proposal from a qualified poultry nutritionist covering basal ration analysis, ingredient COAs, candidate source legal status/purity/contaminants, control and experimental diet rationale, nutrient balance, mixing uniformity, sampling schedule, statistical plan, success criteria, safety and stop rules. Do not use this report as a feed-mixing recipe.','Not measured yet. Representative baseline feed and ordinary eggs from the intended farm/feed system must be sampled; the nutrient target and validated assays are to be selected following feasibility review.','Stage 0 baseline planning estimate 2–4 weeks; Stage 1 randomized replicated pen trial duration to be set by the poultry specialist; Stage 2 repeat selected candidate across confirmation batches and raw-material lots; any human study is optional and requires independent investigators and ethics approval.','Fatty-acid profile using validated GC method; choline and phosphatidylcholine where feasible; iodine per edible portion plus feed/water exposure review; B12/folate validated assays; iron/zinc using validated ICP-OES/ICP-MS or equivalent; protein, moisture, fat and energy; selected nutrient stability, sensory quality and shelf life. Verify that NABL scope covers each test/matrix, and check FSSAI recognition where relevant.','R&D budget and lab prices are not provided as confirmed amounts; request itemised quotes for methods, sample count, turnaround, preparation, taxes and accreditation scope. Record actual quotes and costs after receipt.','[{"code":"G0","name":"Concept approval and expert appointment","window":"Planning Weeks 1–2","status":"Not Started","pass":"Conservative positioning selected; poultry nutritionist and regulatory adviser appointed."},{"code":"G1","name":"Baseline and feasibility","window":"Planning Weeks 2–6","status":"Not Started","pass":"Baseline feed/egg profile; nutrient target and assay confirmed; suppliers screened."},{"code":"G2","name":"Pilot layer trial","window":"Duration set by poultry specialist","status":"Not Started","pass":"Statistically credible nutrient change without unacceptable health, production, egg-quality or safety impact."},{"code":"G3","name":"Independent confirmation batches","window":"After pilot","status":"Not Started","pass":"Multiple batches meet release limits; stability and cost per saleable egg accepted."},{"code":"G4","name":"Label and regulatory review","window":"Before packaging print","status":"Not Started","pass":"Claims, nutrition panel, declarations and marketing assets reviewed."},{"code":"G5","name":"Limited market launch","window":"Only after prior gates","status":"Not Started","pass":"Traceability/QC operational; conservative claims and complaint monitoring live."},{"code":"G6","name":"Optional clinical study","window":"Only if justified","status":"Not Started","pass":"Ethics-approved protocol, funding, independent investigator and prespecified outcomes."}]'::jsonb,'No claim of cognitive benefit; avoid memory, IQ, attention or superactivity claims. Do not formulate feed with children as direct dosing target. Any human study in children requires independent paediatric investigators, ethics review, parental consent and child assent as applicable. Review trademark and FSSAI requirements before using the name or label.',FALSE
WHERE NOT EXISTS (SELECT 1 FROM rnd_projects WHERE project_code='6EGGZ-RND-CHILD-001');

INSERT INTO rnd_projects (project_code,name,alternate_name,product_concept,research_question,candidate_nutrients,scientific_rationale,evidence_references,project_owner,status,protocol_summary,baseline_summary,feed_trial_details,laboratory_plan,cost_notes,milestones,risks_and_limitations,commercial_release_approved)
SELECT '6EGGZ-RND-GLUCO-001','6eggz GlucoBalance','6eggz NutriBalance','Proposed nutrient-characterised table egg concept for consideration within a balanced diet; Research Concept — Not Approved for Commercial Sale.','Can a qualified poultry nutritionist’s controlled and safe trial produce repeatable, measurable egg composition while maintaining layer health, production, egg quality, safety, shelf life and commercial feasibility?','["Protein","Carbohydrate","Proximate composition: moisture, fat, ash, fibre and energy as method-appropriate","Relevant fatty-acid profile; optional omega-3 enrichment only if justified","Vitamin D3/B12/B-complex only if separately justified"]'::jsonb,'The uploaded GlucoBalance report treats this as a nutrient-characterised food, not a diabetes treatment. Eggs contain little carbohydrate and protein, but that does not make a product glucose-lowering; the whole meal, portion, cooking, individual metabolism, medication and overall diet matter. Feed-mediated omega-3 enrichment may support technical feasibility for egg composition, not human diabetes benefits.','[{"source":"6eggz_GlucoBalance_Diabetes_Nutrition_Egg_RnD_Report-1.docx","sections":["Scientific basis and limits","Recommended product design","Feed formulation brief","Controlled layer trial framework","Laboratory testing plan","Human-health evidence plan","India regulatory and claims guardrails","Commercial metrics"]},{"source":"6eggz_GlucoBalance_Diabetes_Nutrition_Egg_RnD_Report-2.pdf","note":"Second version of the same GlucoBalance concept report; handled as duplicate version, not an independent evidence source."},{"title":"FSSAI Advertising & Claims Regulations and amendments","url":"https://www.fssai.gov.in/food-law/regulations/amendments/advertising-claims"},{"title":"FSSAI food testing laboratories","url":"https://www.fssai.gov.in/food-testing/food-laboratories"},{"title":"NABL laboratory search","url":"https://nablwp.qci.org.in/laboratorysearch"}]'::jsonb,'Dhruva Natural Bio Products Pvt Ltd — R&D owner to be assigned','Proposed','Nutritionist must formulate phase-specific basal and experimental layer diets for bird strain/age/production stage, body weight, feed intake, climate and ingredient quality. Review nutrient specifications, mycotoxin risk, fat quality, mineral bioavailability and mixing uniformity. Do not publish inclusion rates before review of the basal diet and trial protocol.','Not measured yet. Establish basal-feed, whole-egg/edible-portion and egg-quality baselines first; carbohydrate must be measured using a validated method, not assumed zero.','Trial arm A basal control; B one justified enrichment; C optional second treatment/level only if it answers a defined question; D optional confirmation treatment with preliminary rationale. Investigator sets bird/pen numbers, replicates, treatments and duration using power calculations. Monitor flock health, mortality, feed intake, production, egg mass, saleable rate, shell quality, sensory quality, stability and nutrient profile.','Whole egg/edible portion: validated proximate composition, protein, fat and carbohydrate methods, energy calculation; yolk fatty-acid profile for omega-3 if intended; optional vitamin tests only if justified; risk-based safety/residue/microbiological tests; shelf life under actual pack and storage conditions. Verify the exact NABL test scope and FSSAI recognition where applicable.','R&D budget and lab prices are not provided as confirmed numbers; request itemised quotes showing methods, sample counts, pricing, turnaround, preparation, taxes and accreditation scope. Log actual costs and quotations when received.','[{"code":"G0","name":"Concept and claims review","status":"Not Started","pass":"Working name legally reviewed; narrow question defined; qualified poultry nutritionist assigned."},{"code":"G1","name":"Baseline and feasibility","status":"Not Started","pass":"Basal ration, feed ingredients and egg profile assessed; assays and trial target agreed."},{"code":"G2","name":"Controlled layer trial","status":"Not Started","pass":"Specialist-designed controlled trial; egg composition and flock outcomes reviewed."},{"code":"G3","name":"Independent laboratory confirmation","status":"Not Started","pass":"Repeatable egg composition; quality, safety and shelf life independently assessed."},{"code":"G4","name":"Regulatory and product-claim review","status":"Not Started","pass":"Name, labels, nutrient claims and marketing reviewed under applicable Indian requirements."},{"code":"G5","name":"Commercial release approval","status":"Not Started","pass":"Prior gates passed; costs and market feasibility reviewed; traceability/QC operational."}]'::jsonb,'No glucose-lowering, diabetes prevention/reversal, medicine replacement or universal suitability claims. A hen-feed or egg-composition trial cannot establish a human clinical outcome. Do not add chromium, cinnamon, herbal extracts or high-dose vitamins solely for blood-sugar marketing; ingredients need poultry-nutrition rationale, legal suitability, safety and evidence. ',FALSE
WHERE NOT EXISTS (SELECT 1 FROM rnd_projects WHERE project_code='6EGGZ-RND-GLUCO-001');

